select g.game_id, g.team_id, g.goalie_id, g.starter_probability, round(g.proj_saves,1) sv, round(g.proj_shots_against,1) sa, round(g.proj_goals_allowed,2) ga, (select string_agg(k,' ') from jsonb_object_keys(g.uncertainty) k) keys, jsonb_typeof(g.uncertainty->'goalie_candidates') t, left((g.uncertainty->'goalie_candidates')::text,500) c from forge_goalie_projections g where g.run_id='26373189-3ebd-4380-b4f4-c6797d469ca9'
